from html import escape as esc
# Individual product photography regenerated from the approved collection direction.
ITEMS=[
 {'id':'everyday-black','name':'The Everyday Tee','colour':'Washed black','line':'ESSENTIALS / 01','asset':'everyday-black-v2.webp','category':'essentials'},
 {'id':'everyday-ivory','name':'The Everyday Tee','colour':'Warm ivory','line':'ESSENTIALS / 02','asset':'everyday-ivory-v2.webp','category':'essentials'},
 {'id':'after-hours','name':'After Hours Tee','colour':'Washed black / sunset print','line':'AFTER HOURS / 03','asset':'after-hours-v2.webp','category':'graphics'},
 {'id':'free-time','name':'Free Time Tee','colour':'Ivory / sunset print','line':'FREE TIME / 04','asset':'free-time-v2.webp','category':'graphics'}
]
def shirt(p,prefix,uid,back=False):
 return '<img class="ohc-shirt'+(' ohc-shirt-detail' if back else '')+'" src="'+prefix+'assets/off-hours/'+p['asset']+'" alt="'+esc(p['name']+' — '+p['colour']+(' enlarged detail' if back else ''))+'" width="1536" height="1024" draggable="false">'
def hanger():
 return '<svg class="ohc-hanger" viewBox="0 0 280 90" aria-hidden="true"><path d="M136 29 C136 18 149 20 149 10 C149 -3 128 -2 130 11 M136 29 L24 77 Q17 83 28 84 H252 Q264 83 255 77 Z" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg>'
def rack(prefix):
 cards=''
 for i,p in enumerate(ITEMS):
  cards+='<button class="ohc-garment" type="button" data-shirt="'+p['id']+'" style="--sway:'+str((-1 if i%2 else 1)*3)+'deg" aria-label="Take '+esc(p['name']+' '+p['colour'])+' off the rack">'+hanger()+shirt(p,prefix,'rail-'+p['id'])+'<span class="ohc-tag"><small>'+p['line']+'</small><strong>'+p['name']+'</strong><span>'+p['colour']+'</span></span></button>'
 return '<section class="ohc-rack-section" id="rail"><div class="ohc-rack-heading"><div><span class="ohc-kicker">THE RAIL / COLLECTION PREVIEW</span><h2>Find your off switch.</h2></div><p>Slide the hangers. Pick your piece.<br>Click a tee to take it off the rack.</p></div><div class="ohc-rail-scene"><div class="ohc-rail-metal" aria-hidden="true"></div><div class="ohc-rail-track" id="ohcRail" tabindex="0" aria-label="Clothing rail. Swipe, drag, or use the arrow buttons to browse.">'+cards+'</div><div class="ohc-rail-floor" aria-hidden="true"></div></div><div class="ohc-rail-controls"><span id="ohcRailStatus" role="status">01 — 04 / FOUR DESIGNS</span><div><button type="button" data-rail-step="-1" aria-label="Browse rail left">←</button><button type="button" data-rail-step="1" aria-label="Browse rail right">→</button></div><span>DRAG / SWIPE TO EXPLORE</span></div></section>'
def dialogs(prefix):
 import json
 data=[{**p,'front':shirt(p,prefix,'detail-front-'+p['id']),'back':shirt(p,prefix,'detail-back-'+p['id'],True)} for p in ITEMS]
 return '<script type="application/json" id="ohcProducts">'+json.dumps(data).replace('</','<\\/')+'</script><dialog class="ohc-product-dialog" id="ohcProduct" aria-labelledby="ohcProductTitle"><button class="ohc-close" data-ohc-close aria-label="Return shirt to rack">×</button><div class="ohc-product-layout"><div class="ohc-product-stage" id="ohcProductStage"></div><div class="ohc-product-copy"><span class="ohc-kicker" id="ohcProductLine"></span><h2 id="ohcProductTitle"></h2><p id="ohcProductColour"></p><p class="ohc-coming">Coming soon</p><p class="ohc-detail-text">A piece from the OFF HOURS CLUB concept collection. Your time. Your terms.</p><div class="ohc-view-switch" aria-label="Garment view"><button type="button" data-ohc-view="front" aria-pressed="true">Full piece</button><button type="button" data-ohc-view="back" aria-pressed="false">Closer look</button></div><fieldset class="ohc-sizes"><legend>Choose a size <span>— preview options</span></legend>'+''.join('<label><input type="radio" name="ohcSize" value="'+s+'"><span>'+s+'</span></label>' for s in ['S','M','L','XL','XXL'])+'</fieldset><button class="ohc-button ohc-add" id="ohcAdd" type="button">Add to demo bag <span>↗</span></button><p class="ohc-feedback" id="ohcFeedback" role="status"></p><p class="ohc-disclaimer">Design concepts only. Pricing, materials, sizing and availability are to be confirmed. No purchase or payment is made.</p></div></div></dialog><dialog class="ohc-bag-dialog" id="ohcBag" aria-labelledby="ohcBagTitle"><button class="ohc-close" data-bag-close aria-label="Close bag">×</button><span class="ohc-kicker">OFF HOURS CLUB</span><h2 id="ohcBagTitle">Your off-hours edit.</h2><div id="ohcBagItems"></div><p class="ohc-disclaimer">Demo bag only. No prices, payments or live orders are connected.</p><button class="ohc-button" data-bag-close type="button">Back to the rail ↗</button></dialog>'
def register_off_hours(g):
 page=g['page']
 for path,prefix,is_shop in [('off-hours-club/','../',False),('off-hours-club/shop/','../../',True)]:
  sub='<div class="ohc-subnav"><a class="ohc-wordmark" href="'+prefix+'off-hours-club/">OFF HOURS CLUB<span>YOUR TIME. YOUR TERMS.</span></a><nav aria-label="OFF HOURS CLUB"><a href="'+prefix+'off-hours-club/shop/"'+(' aria-current="page"' if is_shop else '')+'>The shop</a><a href="#ohcLookbook">The collection</a><button type="button" data-ohc-bag>Bag <span data-ohc-count>0</span></button></nav></div>'
  intro='<section class="ohc-campaign"><img src="'+prefix+'assets/off-hours/campaign-v2.webp" alt="OFF HOURS CLUB editorial concept: friends wearing charcoal and ivory tees on a coastal promenade" fetchpriority="high" width="1536" height="1024"><div class="ohc-campaign-copy"><span class="ohc-kicker">OFF HOURS CLUB / THE FIRST EDIT</span><h1>'+('Made for<br><em>your time.</em>' if not is_shop else 'Good things.<br><em>No rush.</em>')+'</h1><p>Leave the noise behind.<br>Everyday pieces for your off-duty life.</p><a href="#rail" class="ohc-campaign-cta">Explore the collection <span>↗</span></a></div><span class="ohc-campaign-note">YOUR TIME. YOUR TERMS. / COLLECTION 001</span></section>'
  cards=''.join('<button class="ohc-editorial-product" type="button" data-shirt="'+p['id']+'" data-ohc-category="'+p['category']+'"><span class="ohc-editorial-media">'+shirt(p,prefix,'grid-'+p['id'])+'<span class="ohc-product-pick">Take a closer look ↗</span></span><span class="ohc-editorial-caption"><span><strong>'+p['name']+'</strong><small>'+p['colour']+'</small></span><em>Coming soon</em></span></button>' for p in ITEMS)
  look='<section class="ohc-edit" id="ohcLookbook"><div class="ohc-edit-heading"><div><span class="ohc-kicker">LESS NOISE. MORE FEELING.</span><h2>The first edit.</h2></div><div class="ohc-edit-filters" aria-label="Collection filter"><button type="button" data-edit-filter="all" aria-pressed="true">All pieces</button><button type="button" data-edit-filter="essentials" aria-pressed="false">Essentials</button><button type="button" data-edit-filter="graphics" aria-pressed="false">Graphic tees</button></div></div><div class="ohc-edit-grid">'+cards+'</div></section><section class="ohc-manifesto"><span class="ohc-kicker">THIS IS OFF HOURS CLUB</span><h2>Not every hour<br>needs a purpose.</h2><p>The long way home. The last light of the day. A little space to just be. This is your uniform for everything after everything.</p><a class="ohc-text-link" href="#rail">Find your piece ↗</a><span class="ohc-manifesto-mark">OHC.</span></section>'
  body='<div class="ohc-world">'+sub+intro+rack(prefix)+'<div class="ohc-brand-line">WORK ENDS. <i>LIFE DOESN’T.</i></div>'+look+'<footer class="ohc-footer"><strong>OFF HOURS CLUB</strong><p>Your time. Your terms.</p><a href="'+prefix+'">Back to PRIMO ↗</a><span>Collection concept / shop demonstration</span></footer>'+dialogs(prefix)+'</div>'
  page(path,'OFF HOURS CLUB '+('Shop — Browse the Clothing Rail' if is_shop else '— Your Time. Your Terms.')+' | PRIMO','Explore OFF HOURS CLUB clothing concepts on an interactive sliding rail. Pick a tee, explore the designs and build a demo bag. Collection preview only.','OFF HOURS CLUB','',body,image='off-hours/campaign-v2.webp',kicker='OFF HOURS CLUB',extra={'ohc':True},label='Shop' if is_shop else 'OFF HOURS CLUB')
